    best=[]
    for a in [-2,-1,1,2]:
        for b in [-2,-1,1,2]:
            for m in range(2,15):
                dd={}
                ok=True
                for i in range(h):
                    for j in range(w):
                        if I[i,j]!=0:
                            key=(a*i+b*j)%m
                            if key in dd and dd[key]!=int(I[i,j]): ok=False;break
                            dd[key]=int(I[i,j])
                        if ok:
                            if I[i,j]==0 and (dd.get(key,m)!=B[i,j] or True): pass
                if ok:
                    best.append((a,b,m))
    return best
