h,w=I1.shape
def solve(I):
    h,w=I.shape; F=I.copy()
    # upward fill
    for j in range(w):
        for i in range(h-1,-1,-1):
            if F[i,j]!=0: continue
            for k in range(1,i+1):
                if I[i-k,j]!=0: F[i,j]=I[i-k,j]; break
    for j in range(w):
        for i in range(1,h):
            if F[i,j]==0 and I[i,j]!=0: continue
            if F[i,j]!=0: continue
            for k in range(1,h-i):
                if I[i+k,j]!=0: F[i,j]=I[i+k,j]; break
    return F
