import numpy as np
def F(I,priority):
    h,w=I.shape; F=I.copy()
    dirs={'U':(-1,0),'D':(1,0)}
    for _ in range(6):
        changed=False
        for nm in priority:
            di,dj=dirs[nm]
            for i in range(h):
                for j in range(w):
                    if F[i,j]!=0: continue
                    found=False
                    k=1
                    while True:
                        a,b=i+k*di,j+k*dj
                        if not(0<=a<h and 0<=b<w): break
                        if F[a,b]!=0:
                            F[i,j]=int(F[a,b]); found=True; break
                        k+=1
                    if found: changed=True; break
                if found: break
            if found: break
        if not changed: break
    return F
for name,I,B in [('d1',I1,B1),('d2',I2,B2)]:
    for p in [['D'],['U'],['D','U'],['U','D']]:
